/// The sending queue and the external connection the packs go on.
pub struct Transmitter {
    /// Packs put from any thread, taken by the transport — and emptied by a close from any thread: without a lock, each pack
    /// by value in its slot, filled and read in place ( the in-place side of the `RingBuffer` ).
    sending_: crate::lib::collections::RingBuffer<transmitter::DataPass>,
    /// The external connection the packs go on: read with one load - a
    /// connection of a host is a slot of it for good ( `TCP::Pool` ), nothing it sat on is freed under a reader.
    pub(crate) ext_connection: crate::lib::adhoc::handlers::Handler<dyn crate::lib::adhoc::connection::external::External>,
    /// What the application hears of the packs this connection sends: set, replaced or taken away
    /// with `handler.exchange( … )` at any time.
    pub handler: crate::lib::adhoc::handlers::Handler<dyn crate::lib::adhoc::connection::transmitter::EventsHandler<transmitter::Pack>>,
    
}

impl Transmitter {
    pub fn new( power_of_2_sending_queue_size: u32 ) -> Self {
        Self { sending_: crate::lib::collections::RingBuffer::new( power_of_2_sending_queue_size ), ext_connection: crate::lib::adhoc::handlers::Handler::new(), handler: crate::lib::adhoc::handlers::Handler::new() }
    }

    #[inline]
    pub fn is_open( &self ) -> bool { self.ext_connection.get().is_some_and( |__e| __e.is_open() ) }

    /// Takes every pack still waiting out of the queue: a relayed frame among them is told its outbound is
    /// gone. Any thread.
    pub fn discard( &self ) {
        self.sending_.clear_in_place( |__p| {
            crate::lib::adhoc::connection::transmitter::on_error::tx( crate::lib::adhoc::connection::transmitter::on_error::TxOnError::DiscardedOnClose, &format_args!( "pack {} never sent: the queue is discarded", __p.src.__id() ) );
            Self::unsent( &__p.src );
            __p.src = transmitter::Pack::None;
            __p.actor.inst = None // the instance it was queued for: not kept by a free slot
        } );
    }

    /// The pack `src` goes unsent: a relayed frame is told its outbound is gone, a
    /// burst of a tunnel drops the pack it cut and opens its gate.
    fn unsent( src: &transmitter::Pack ) {
        
        
    }

    /// The connection is closed, its transport sends no more: the pack in flight first - its
    /// wrapper is a slot of the queue - then every pack still waiting.
    fn close( &self ) {
        if self.sending_.has_taken() {
            // SAFETY: the transport, the consumer of the queue, is done
            let __p = unsafe { self.sending_.taken() };
            Self::unsent( &__p.src );
            __p.src = transmitter::Pack::None;
            __p.actor.inst = None;
            self.sending_.free();
        }
        self.discard();
    }

    /// The connection closes once what is in flight is out; what is queued is discarded.
    pub fn last_transmission( &self ) { 
        if let Some( __e ) = self.ext_connection.get() { __e.set_transmit_timeout( -__e.transmit_timeout().abs() ); }
        self.discard();
    }

    #[inline]
    fn put( &self, __fill: impl FnOnce( &mut transmitter::DataPass ) ) -> bool {
    
        if !self.is_open() { return false; }
        match self.sending_.put( |__p| { __fill( __p ); true } ) {
            None => false, // the queue is full, or was and less than a quarter of it is free yet
            Some( __wake ) => {
                if __wake { if let Some( __e ) = self.ext_connection.get() { __e.wake_transmit(); } } // the runner sleeps: it is to be woken
                true
            }
        }
    }

    /// A pack captured as it was received goes out on this connection as it came: `false` —
    /// refused, the queue is full or the connection closes.
    pub fn sending_put_captured( &self, src: crate::lib::adhoc::connection::receiver::bytes_copy::Capture ) -> bool {
        self.put( |__p| { __p.src = transmitter::Pack::Captured( src ); __p.value = 0; __p.actor = ActorId::default(); __p.kind = 0; __p.headers.init_(); } )
    }

    
    
    
    /// A pack with no header.
    pub fn sending_put( &self, actor: ActorId, kind: i32, src: transmitter::Pack, value: u64 ) -> bool {
        self.put( |__p| { __p.src = src; __p.value = value; __p.headers.address( &actor ); __p.actor = actor; __p.kind = kind; __p.headers.init_(); } )
    }

}

/// The transport takes the packs to send here: `&Connection` is the
/// host — the queue is the only state, and it has its own consumer side.
impl crate::lib::adhoc::connection::transmitter::TxHost for &Connection {
    
    #[inline(always)]
    fn speed( &self ) -> Option<&std::sync::atomic::AtomicI64> { Some( &self.transmit_speed ) }
    
    
    
    /// The queue is empty and the line has been silent: the service pack Pulse_, its id alone.
    fn pulse( &mut self, __dst: &mut [u8] ) -> usize {
        if __dst.len() < 1 || !self.transmitter.ext_connection.get().is_some_and( |__e| __e.take_pulse() ) { return 0; }
        __dst[..1].copy_from_slice( &255u64.to_le_bytes()[..1] );
        1
    }
    fn on_serializing( &mut self ) -> bool { 
        let conn = *self;
        if conn.transmitter.sending_.has_taken() { // a pack cut and dropped ( abandon ) - a journal kept none of it: who waits for it hears, its place is given back
            // SAFETY: the transport is the consumer of the queue
            let __p = unsafe { conn.transmitter.sending_.taken() };
            Transmitter::unsent( &__p.src );
            __p.src = transmitter::Pack::None;
            __p.actor.inst = None;
            conn.transmitter.sending_.free();
        }
        loop {
            if !conn.transmitter.sending_.take() { return false; } // empty: the producer of the next pack wakes the runner
            
//#region > OnSerializing
//#endregion > ÿÿ.Transmitter.OnSerializing
            // SAFETY: the transport is the consumer of the queue, and the slot is taken until on_serialized
            let __sending_out = unsafe { conn.transmitter.sending_.taken() };
            if __sending_out.on_serializing( conn ) { return true; }
            __sending_out.src = transmitter::Pack::None; // the pack declined: its slot is free
            __sending_out.actor.inst = None;
            conn.transmitter.sending_.free();
        }
    }

    fn get_bytes( &mut self, __dst: &mut crate::lib::adhoc::connection::transmitter::Tx<'_> ) -> bool {
        // SAFETY: as in on_serializing
        unsafe { self.transmitter.sending_.taken() }.get_bytes( __dst )
    }

    fn on_serialized( &mut self ) {
        let conn = *self;
//#region > OnSerialized
//#endregion > ÿÿ.Transmitter.OnSerialized
        // SAFETY: as in on_serializing
        let __sending_out = unsafe { conn.transmitter.sending_.taken() };
        __sending_out.on_serialized( conn );
    }

    /// The application's handler hears the pack start: a copy it sets in `__tx` gets the pack.
    fn serializing( &mut self, __tx: &mut crate::lib::adhoc::connection::transmitter::TxState ) {
        // SAFETY: as in on_serializing
        if let Some( __h ) = self.transmitter.handler.get() { __h.on_serializing( __tx, &unsafe { self.transmitter.sending_.taken() }.src ); }
    }

    /// The application's handler hears the pack out, then its slot is free.
    fn serialized( &mut self, __tx: &mut crate::lib::adhoc::connection::transmitter::TxState ) {
        let conn = *self;
        // SAFETY: as in on_serializing
        let __sending_out = unsafe { conn.transmitter.sending_.taken() };
        if let Some( __h ) = conn.transmitter.handler.get() { __h.on_serialized( __tx, &__sending_out.src ); }
        __sending_out.src = transmitter::Pack::None;
        __sending_out.actor.inst = None; // the instance it was queued for: not kept by a free slot
        conn.transmitter.sending_.free(); // the slot of the pack is free for the next one
    }
}

